#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <blosc2.h>

int main() {
  blosc_init();
  blosc2_cparams cparams = BLOSC2_CPARAMS_DEFAULTS;
  cparams.typesize = 4;
  cparams.compcode = BLOSC_BLOSCLZ;
  cparams.clevel = 5;
  blosc2_dparams dparams = BLOSC2_DPARAMS_DEFAULTS;
  blosc2_storage storage = {.cparams=&cparams, .dparams=&dparams};
  blosc2_schunk* schunk = blosc2_schunk_new(storage);
  int32_t chunksize = 1000;
  uint8_t* data = malloc(chunksize);
  for (int i=0;i<chunksize;i++) data[i] = i % 251;
  blosc2_schunk_append_buffer(schunk, data, chunksize);
  blosc2_schunk_append_buffer(schunk, data, chunksize);
  blosc2_schunk_append_buffer(schunk, data, chunksize);
  uint8_t* sframe = NULL;
  int64_t len = blosc2_schunk_to_sframe(schunk, &sframe);
  FILE* f = fopen("/tmp/frame.bin","wb");
  fwrite(sframe,1,len,f);
  fclose(f);
  printf("frame len=%lld\n", (long long)len);
  for (int i=0;i<82;i++) printf("%02x ", sframe[i]);
  printf("\n");
  free(sframe);
  free(data);
  blosc2_schunk_free(schunk);
  blosc_destroy();
  return 0;
}
EOF
